<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Config;use App\Core\Cron;use App\Core\Crypto;use App\Core\DB;use App\Core\Request;use App\Core\Response;use App\Services\JobService;use App\Services\StripeService;final class HealthController extends AdminController{public function index(Request $x):Response{$W=[];$W[]=['label'=>'PHP','ok'=>true,'detail'=>PHP_VERSION];$W[]=['label'=>t('admin.health_db'),'ok'=>true,'detail'=>DB::driver()];$X=true;$J='';try{$J=Crypto::publicKeyB64();}catch(\Throwable){$X=false;}$W[]=['label'=>t('admin.health_keys'),'ok'=>$X,'detail'=>$X?substr($J,0,16).'…':t('admin.health_missing')];$q=Cron::lastRun();$m=$q&&strtotime($q)>time()-2*3600;$W[]=['label'=>'Cron','ok'=>$m,'detail'=>$q?date_fmt($q,'d/m/Y H:i').' UTC':t('admin.health_never')];$W[]=['label'=>t('admin.health_queue'),'ok'=>JobService::failedCount()===0,'detail'=>JobService::pendingCount().' '.t('admin.pending').', '.JobService::failedCount().' '.t('admin.failed')];$W[]=['label'=>t('admin.health_payment'),'ok'=>true,'detail'=>StripeService::mode()];$W[]=['label'=>t('admin.health_mail'),'ok'=>true,'detail'=>(string)(\App\Models\Setting::get('mail')['driver']??Config::get('mail.driver','log'))];foreach(['storage/logs','storage/cache','storage/releases','storage/invoices','storage/media','storage/sessions']as $Q){$W[]=['label'=>$Q,'ok'=>is_writable(TP_ROOT.'/'.$Q),'detail'=>is_writable(TP_ROOT.'/'.$Q)?t('admin.writable'):t('admin.not_writable')];}$D=@disk_free_space(TP_ROOT);$W[]=['label'=>t('admin.health_disk'),'ok'=>$D===false||$D>500*1024*1024,'detail'=>$D===false?'?':round($D/1024/1024/1024,1).' Go'];$W[]=['label'=>'HTTPS','ok'=>$x->isSecure()||str_contains((string)Config::get('app.url'),'127.0.0.1')||str_contains((string)Config::get('app.url'),'localhost'),'detail'=>$x->isSecure()?'ok':t('admin.health_no_https')];$P=DB::fetchAll('SELECT * FROM {{cron_runs}} ORDER BY id DESC LIMIT 40');$E=DB::fetchAll('SELECT * FROM {{mail_log}} ORDER BY id DESC LIMIT 20');$e=DB::fetchAll('SELECT * FROM {{jobs}} ORDER BY id DESC LIMIT 20');$g=[];foreach(glob(TP_ROOT.'/storage/logs/*.log')?:[]as $o){$g[]=['name'=>basename($o),'size'=>filesize($o),'mtime'=>filemtime($o)];}return $this->view('admin/health',['checks'=>$W,'runs'=>$P,'mails'=>$E,'jobs'=>$e,'logs'=>$g,'meta'=>['title'=>t('admin.health')]]);}public function runCron(Request $G):Response{$a=Cron::run();$this->flash('success','Cron : '.implode(' · ',array_map(fn($g,$c)=>$g.' → '.$c,array_keys($a),$a)));return $this->redirect('/admin/health');}}